// Fixed std-only CPU child actions; no model/native executable invocation.
#include "supervisor.hpp"
#include <iostream>
using namespace hs::n1chain;
static BoundedLaunchSpec spec(double seconds){BoundedLaunchSpec s;s.controller={::getpid(),controller_start_ticks(::getpid()),controller_boot_id()};s.deadline_wall=launch_clock(CLOCK_REALTIME)+seconds;s.deadline_mono=launch_clock(CLOCK_MONOTONIC)+seconds;return s;}
static FD logfile(const std::string&p){FD f(::open(p.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW,0600));checked(f.n,"fresh boundary CPU log");return f;}
int main(int argc,char**argv){try{
 require(argc==2&&argv[1][0]=='/',"fresh absolute boundary fixture root required");const std::string root=argv[1];checked(::mkdir(root.c_str(),0700),"fresh boundary fixture");unsigned passed=0;
 {auto s=spec(2);const auto r=launch_detail::supervise_bridge(s,[]{},[](pid_t,int){});require(r.status=="OWNED_CHILD_EXITED"&&r.exit_confirmed,"before deadline must complete");passed++;}
 {auto s=spec(.4);auto out=logfile(root+"/late.out"),err=logfile(root+"/late.err");s.stdout_fd=out.n;s.stderr_fd=err.n;s.per_log_bytes=64;BoundedLogIO io;unsigned syncs=0;io.sync=[&](int fd){syncs++;const auto r=::fsync(fd);if(syncs==1)::poll(nullptr,0,600);return r;};const auto r=launch_detail::supervise_bridge(s,[]{::write(STDOUT_FILENO,"x",1);},[](pid_t,int){},io);require(syncs>0&&r.status=="DEADLINE_STOP_SENT"&&r.exit_confirmed&&r.output_partial&&!r.stdout_complete&&!r.stderr_complete,"fsync crossing deadline must not pass");passed++;}
 {const auto owner=::fork();checked(owner,"fork fixed CPU owner");if(owner==0){::poll(nullptr,0,250);::_exit(0);}auto s=spec(2);s.controller={owner,controller_start_ticks(owner),controller_boot_id()};auto out=logfile(root+"/owner.out"),err=logfile(root+"/owner.err");s.stdout_fd=out.n;s.stderr_fd=err.n;s.per_log_bytes=64;BoundedLogIO io;unsigned syncs=0;io.sync=[&](int fd){syncs++;const auto r=::fsync(fd);if(syncs==1)::poll(nullptr,0,400);return r;};const auto r=launch_detail::supervise_bridge(s,[]{::write(STDOUT_FILENO,"x",1);},[](pid_t,int){},io);int status=0;checked(::waitpid(owner,&status,0),"reap own fixed CPU owner");require(syncs>0&&r.status=="CONTROLLER_LOST_STOP_SENT"&&r.exit_confirmed&&r.output_partial,"owner death during sync must not pass");passed++;}
 {auto s=spec(.1);const auto forbidden=root+"/FORBIDDEN_CHILD_RAN";bool rejected=false;try{(void)launch_detail::supervise_bridge(s,[&]{const auto f=::open(forbidden.c_str(),O_WRONLY|O_CREAT|O_EXCL,0600);if(f>=0)::close(f);},[](pid_t,int){::poll(nullptr,0,180);});}catch(const std::exception&){rejected=true;}require(rejected&&::access(forbidden.c_str(),F_OK)<0&&errno==ENOENT,"expired preexec permit must remain closed");passed++;}
 std::cout<<"{\"status\":\"CPU_SUPERVISOR_BOUNDARY_PASS\",\"tests\":"<<passed<<",\"native_model_context_placement_forward_calls\":0}\n";return 0;
 }catch(const std::exception&e){std::cerr<<"CPU_BOUNDARY_FAIL "<<e.what()<<'\n';return 1;}}
